    },
    {
      "id": "F7",
      "description": "Selective prediction and calibrated risk control under distribution shift: abstention, coverage-risk control, and calibration methods intended to remain reliable as deployment distributions change."
    },
    {
      "id": "F8",
      "description": "Budgeted information acquisition and resource-rational stopping: policies that trade expected information benefit against retrieval, computation, latency, token, or monetary costs."
    },
    {
      "id": "F12",
      "description": "Bounded information-seeking tool planning: planning sequences of external information-seeking actions where later operations depend on evidence observed from earlier ones."
    },
    {
      "id": "F13",
      "description": "Joint adaptive retrieval controllers: integrated policies combining multiple retrieval-control functions such as decomposition, iterative acquisition, sufficiency assessment, stopping, and resource constraints."
    }
